WITH counts AS (SELECT c.category_name,p.sku,SUM(i.quantity) AS paid_units FROM categories c JOIN products p ON p.category_id=c.category_id JOIN order_items i ON i.product_id=p.product_id JOIN orders o ON o.order_id=i.order_id WHERE o.status='paid' GROUP BY c.category_id,p.product_id,c.category_name,p.sku), ranked AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY category_name ORDER BY paid_units DESC,sku) AS rn FROM counts) SELECT category_name,sku,paid_units FROM ranked WHERE rn=1 ORDER BY category_name;
